export const EMPTY='À compléter';
export const blankState=()=>({schema:'lnia-s20',version:1,fields:{targetSource:'text',target:'pieces/fiche-cible.html',actionPosition:'end',status:'À COMPLÉTER',diffusion:'Non publié'},v1:null,v1Html:'',checks:Array(7).fill(false),quiz:Array(8).fill(null),quizDone:false,known:[],cardOrder:Array.from({length:12},(_,i)=>i),card:0,demo:{},updatedAt:null});
const cleanFields=value=>Object.fromEntries(Object.entries(value||{}).filter(([k,v])=>/^[a-zA-Z][a-zA-Z0-9]*$/.test(k)&&typeof v==='string'&&!['__proto__','constructor','prototype'].includes(k)).map(([k,v])=>[k,v.slice(0,40000)]));
export function normalizeState(value){
 if(!value||value.schema!=='lnia-s20'||value.version!==1)throw new Error('Ce fichier n’est pas un carnet S20 version 1.');
 const out=blankState();out.fields={...out.fields,...cleanFields(value.fields)};out.v1=value.v1&&typeof value.v1==='object'?cleanFields(value.v1):null;out.v1Html=typeof value.v1Html==='string'?value.v1Html.slice(0,1000000):'';
 out.checks=out.checks.map((_,i)=>value.checks?.[i]===true);out.quiz=out.quiz.map((_,i)=>Number.isInteger(value.quiz?.[i])&&value.quiz[i]>=0&&value.quiz[i]<3?value.quiz[i]:null);out.quizDone=value.quizDone===true;
 out.known=Array.isArray(value.known)?[...new Set(value.known.filter(x=>Number.isInteger(x)&&x>=0&&x<12))]:[];
 if(Array.isArray(value.cardOrder)&&value.cardOrder.length===12&&new Set(value.cardOrder).size===12&&value.cardOrder.every(x=>Number.isInteger(x)&&x>=0&&x<12))out.cardOrder=value.cardOrder;
 out.card=Number.isInteger(value.card)&&value.card>=0&&value.card<12?value.card:0;
 if(value.demo&&typeof value.demo==='object')for(const[k,v]of Object.entries(value.demo)){if(!v||typeof v!=='object'||['__proto__','constructor','prototype'].includes(k))continue;out.demo[k]={expect:typeof v.expect==='string'?v.expect.slice(0,4000):'',observed:typeof v.observed==='string'?v.observed.slice(0,4000):'',choice:Number.isInteger(v.choice)&&v.choice>=0&&v.choice<3?v.choice:null};}
 out.updatedAt=typeof value.updatedAt==='string'?value.updatedAt:null;
 if(!['À COMPLÉTER','À REVOIR','À VALIDER','VALIDÉ'].includes(out.fields.status))out.fields.status='À COMPLÉTER';
 if(!['text','file'].includes(out.fields.targetSource))out.fields.targetSource='text';if(!['start','end'].includes(out.fields.actionPosition))out.fields.actionPosition='end';
 if(out.fields.status==='VALIDÉ'&&validationMissing(out).length)out.fields.status='À VALIDER';return out;
}
export function fromS19(value){if(!value||value.schema!=='lnia-s19'||value.version!==1)throw new Error('Carnet S19 version 1 attendu.');const out=blankState(),keys=['project','audience','need','source','title','hook','problem','promise','benefit','action','target','targetSource','targetTitle','targetText','targetFileName'];const old=cleanFields(value.fields);for(const k of keys)if(old[k])out.fields[k]=old[k];out.fields.reference='04-WEB/page-simple-v1.html · carnet S19';out.v1={...out.fields};return out;}
export function safeTarget(value=''){const s=value.trim();if(!s||/[^a-zA-Z0-9._/-]/.test(s)||s.startsWith('/')||s.split('/').some(x=>x==='..'||x==='.'||!x))return '';return s;}
export function packetTarget(value=''){const s=safeTarget(value);return /^pieces\/[a-zA-Z0-9_-][a-zA-Z0-9._-]*\.(html|pdf|txt|md)$/i.test(s)?s:'';}
export const wordCount=text=>String(text||'').trim().split(/\s+/u).filter(Boolean).length;
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const positionText=x=>x==='end'?'Après les bénéfices':x==='start'?'Sous l’accroche':x;
const e=escapeHtml,v=(f,k)=>f?.[k]?.trim()||EMPTY;
export function validationMissing(state){const f=state.fields,need=['project','audience','need','reference','source','title','hook','problem','promise','benefit','action','target','task','readerOne','dateOne','deviceOne','observedOne','changed','reason','prediction','readerTwo','dateTwo','deviceTwo','observedTwo','comparison','reopened','proofS17','proofS18','proofS19','proofS20','moduleReview','pilot','reviewDate','review'];return need.filter(k=>!f[k]?.trim()).concat(state.v1?[]:['V1 conservée']).concat(state.checks.every(Boolean)?[]:['sept gestes à observer']).concat(packetTarget(f.target)?[]:['cible relative exploitable']).concat(f.targetSource==='file'?(f.targetFileName?[]:['fiche sélectionnée']):['targetTitle','targetText'].filter(k=>!f[k]?.trim()));}
export function planText(state,which='v2'){const f=which==='v1'?state.v1||{}:state.fields;const link=safeTarget(f.target)?`[${v(f,'action').replace(/[\[\]]/g,'')}](${safeTarget(f.target)})`:'Action et fiche à compléter.';return `# ${v(f,'title')}\n\n${v(f,'hook')}\n\n${f.actionPosition==='start'?link+'\n\n':''}## Le besoin\n\n${v(f,'problem')}\n\n## La proposition\n\n${v(f,'promise')}\n\n## Le bénéfice\n\n${v(f,'benefit')}\n\n${f.actionPosition!=='start'?link+'\n':''}`;}
const pageCSS='body{margin:0;font:18px/1.7 system-ui,sans-serif;color:#142b44;background:#f4f7fb}header{background:#071b33;color:#fff;padding:22px max(6vw,20px);border-bottom:4px solid #d4aa57}main{max-width:780px;margin:40px auto;padding:0 24px}h1{font-size:clamp(32px,6vw,52px);line-height:1.12;letter-spacing:-.03em}h2{font-size:23px;margin-top:36px}p{white-space:pre-line}.action{display:inline-block;background:#071b33;color:white;padding:14px 22px;border-radius:5px;font-weight:700;text-decoration:none;margin:22px 0}a:focus-visible{outline:3px solid #d4aa57;outline-offset:5px}footer{border-top:1px solid #cbd7e1;margin-top:48px;padding:20px;color:#53677e;font-size:14px}@media print{body{background:white}.action{background:transparent;color:#071b33;border:1px solid}}';
export function pageHtml(state,which='v2'){if(which==='v1'&&state.v1Html)return state.v1Html;const f=which==='v1'?state.v1||{}:state.fields,t=safeTarget(f.target),a=t?`<a class="action" href="${e(t)}">${e(v(f,'action'))}</a>`:'<p>Fiche à joindre avant diffusion.</p>';return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta name="description" content="${e(v(f,'hook'))}"><meta name="theme-color" content="#071b33"><title>${e(v(f,'title'))}</title><style>${pageCSS}</style></head><body><header>${e(v(f,'project'))}</header><main><h1>${e(v(f,'title'))}</h1><p>${e(v(f,'hook'))}</p>${f.actionPosition==='start'?a:''}<h2>Le besoin</h2><p>${e(v(f,'problem'))}</p><h2>La proposition</h2><p>${e(v(f,'promise'))}</p><h2>Le bénéfice</h2><p>${e(v(f,'benefit'))}</p>${f.actionPosition!=='start'?a:''}<footer>Version ${which==='v1'?'V1':'V2'}</footer></main></body></html>`;}
export function targetHtml(state){const f=state.fields;return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${e(v(f,'targetTitle'))}</title><style>${pageCSS}</style></head><body><header>${e(v(f,'project'))}</header><main><h1>${e(v(f,'targetTitle'))}</h1><p>${e(v(f,'targetText'))}</p></main></body></html>`;}
export function comparisonText(state){const labels={title:'Titre',hook:'Accroche',problem:'Problème',promise:'Promesse',benefit:'Bénéfices',action:'Libellé',target:'Destination',actionPosition:'Emplacement'};return Object.entries(labels).filter(([k])=>(state.v1?.[k]||'')!==(state.fields[k]||'')).map(([k,label])=>`${label}\nAvant : ${k==='actionPosition'?positionText(v(state.v1,k)):v(state.v1,k)}\nAprès : ${k==='actionPosition'?positionText(v(state.fields,k)):v(state.fields,k)}`).join('\n\n')||'Aucune différence relevée dans les champs. Relisez votre version et votre motif.';}
export function proofText(state,data){const f=state.fields;return `# Preuve S20 — Correction et essai lecteur\n\nProjet : ${v(f,'project')}\nStatut pédagogique : ${v(f,'status')}\nDiffusion : ${v(f,'diffusion')}\nV1 : [page-simple-v1.html](../04-WEB/page-simple-v1.html)\nV2 : [page-simple-v2.html](../04-WEB/page-simple-v2.html)\nFiche : ${safeTarget(f.target)?`[Pièce cible](../04-WEB/${safeTarget(f.target)})`:'À compléter'}\nRéférence héritée : ${v(f,'reference')}\nSource : ${v(f,'source')}\n\n## Premier essai sans aide orale\n\nConsigne : ${v(f,'task')}\nLecteur : ${v(f,'readerOne')}\nDate : ${v(f,'dateOne')}\nAppareil et navigateur : ${v(f,'deviceOne')}\nGeste, parole et résultat observés : ${v(f,'observedOne')}\n\n## Correction\n\nÉlément et extrait avant/après : ${v(f,'changed')}\nMotif : ${v(f,'reason')}\nEffet attendu : ${v(f,'prediction')}\n\nDifférences des champs du carnet :\n\n${comparisonText(state)}\n\n## Deuxième essai\n\nConsigne conservée : ${v(f,'task')}\nLecteur : ${v(f,'readerTwo')}\nDate : ${v(f,'dateTwo')}\nAppareil et navigateur : ${v(f,'deviceTwo')}\nGeste, parole et résultat observés : ${v(f,'observedTwo')}\nComparaison et limites : ${v(f,'comparison')}\nRéouverture du paquet et des exports : ${v(f,'reopened')}\n\n## Revue\n\n${data.criteria.map((c,i)=>`- [${state.checks[i]?'x':' '}] ${c}`).join('\n')}\n\nPilote : ${v(f,'pilot')}\nDate : ${v(f,'reviewDate')}\nObservation et décision : ${v(f,'review')}\nStatut : ${v(f,'status')}\nPièce ou action attendue : ${v(f,'nextAction')}\n\nLa recette technique, la validation pédagogique et la décision de diffusion sont distinctes. Aucun résultat n’est établi par le score du quiz.\n`;}
export function indexText(state){return `# Index du portfolio — Module 05\n\n| Séance | Production | Preuve |\n| --- | --- | --- |\n| S17 | [Plan](../04-WEB/structure-page-projet.md) | [Preuve S17](preuve-S17.md) |\n| S18 | [Contenu](../04-WEB/contenu-page-projet.md) | [Preuve S18](preuve-S18.md) |\n| S19 | [V1](../04-WEB/page-simple-v1.html) | [Preuve S19](preuve-S19.md) |\n| S20 | [V2](../04-WEB/page-simple-v2.html) | [Preuve S20](preuve-S20.md) |\n\nStatut S20 : ${v(state.fields,'status')}\n\nCopiez vos vrais plan S17, contenu S18 et preuves S17 à S19 aux chemins indiqués ou adaptez les liens. Ces fichiers antérieurs ne sont pas fabriqués par le carnet S20. Fusionnez ce tableau avec votre index existant.\n\n[Preuve globale](preuves-module-05.md) · [Relais S21](relais-S21.md)\n`;}
export function moduleText(state){const f=state.fields;return `# Preuve globale — Module 05\n\nProjet : ${v(f,'project')}\n\n## Quatre preuves effectivement rouvertes\n\nS17 : ${v(f,'proofS17')}\nS18 : ${v(f,'proofS18')}\nS19 : ${v(f,'proofS19')}\nS20 : ${v(f,'proofS20')}\n\n## Bilan\n\n${v(f,'moduleReview')}\n\nV1 et V2 : [V1](../04-WEB/page-simple-v1.html) · [V2](../04-WEB/page-simple-v2.html)\nCorrection et motif : ${v(f,'reason')}\nComparaison réelle : ${v(f,'comparison')}\nPoints ouverts : ${v(f,'nextAction')}\n\nPilote : ${v(f,'pilot')}\nDate : ${v(f,'reviewDate')}\nObservation et décision : ${v(f,'review')}\nStatut : ${v(f,'status')}\nDiffusion : ${v(f,'diffusion')}\n`;}
export function relayText(state){const f=state.fields;return `# Relais S20 vers S21 — Module 06\n\nSéance et version : S20 / V2\nFichiers : [V1](../04-WEB/page-simple-v1.html), [V2](../04-WEB/page-simple-v2.html), [preuve S20](preuve-S20.md), [index](index-portfolio.md), [bilan Module 05](preuves-module-05.md).\nFiche cible : ${v(f,'target')}\nCorrection et motif : ${v(f,'reason')}\nEssais et résultats : ${v(f,'observedOne')} / ${v(f,'observedTwo')}\nComparaison et limite : ${v(f,'comparison')}\nPièce manquante ou essai à faire : ${v(f,'nextAction')}\nDécision du pilote : ${v(f,'status')}\nNom, date et observation : ${v(f,'pilot')} / ${v(f,'reviewDate')} / ${v(f,'review')}\nDiffusion : ${v(f,'diffusion')}\n\n## Premier geste S21\n\nOuvrir le dossier du Module 05. Inventorier page V1, page V2, fiche, README, sources et quatre preuves. Repérer la racine du projet et les fichiers à conserver pour le suivi avec Git et GitHub. Choisir les exclusions avant de préparer le versionnement. L’horaire et la date de S21 restent à communiquer par le formateur.\n`;}
export function packetReadme(state){return `# Mon dossier S20\n\nProjet : ${v(state.fields,'project')}\nStatut : ${v(state.fields,'status')}\nDiffusion : ${v(state.fields,'diffusion')}\n\nExtraire tout le dossier. Ouvrir 04-WEB/page-simple-v1.html puis 04-WEB/page-simple-v2.html. Ouvrir leur fiche. La même fiche accompagne les deux versions. Le HTML original V1 est conservé si vous l’avez importé. Sinon V1 est reconstruite à partir des champs figés du carnet.\n\nComparer les deux essais dans 06-PORTFOLIO/preuve-S20.md. Copier les vraies preuves S17 à S19, le plan S17 et le contenu S18 depuis votre dossier antérieur avant la revue globale. Adapter l’index si vos noms diffèrent.\n\nCorrection : ${v(state.fields,'reason')}\nPoints ouverts : ${v(state.fields,'nextAction')}\n\nCe ZIP prépare la remise locale. Il ne publie aucun site.\n`;}
export function exampleState(c){const x=blankState();x.fields={...x.fields,project:c.title+' — cas fictif',audience:c.public,need:c.need,reference:'04-WEB/page-simple-v1.html · exemple fictif',source:c.source,mission:'Corriger un élément après un essai lecteur.',constraints:'Conserver les faits et la fiche.',title:c.titlePage,hook:c.hook,problem:c.problem,promise:c.promise,benefit:c.benefit,action:c.action,target:c.targetPath,targetTitle:c.action,targetText:c.source+'\n\n'+c.items.map(([a,b])=>a+'\n'+b).join('\n\n')+'\n\nCas fictif pédagogique.',task:'Expliquez ce projet puis ouvrez la fiche proposée.'};x.fields[c.changeKey]=c.before;x.v1={...x.fields};x.fields[c.changeKey]=c.after;x.fields.changed=positionText(c.before)+' → '+positionText(c.after);x.fields.reason=c.reason;x.fields.prediction=c.expected;return x;}
